import{_ as t,c as e,o,a4 as a}from"./chunks/framework.BYxathSa.js";const C=JSON.parse('{"title":"Q12：useContext 与 Context API 如何跨组件传值","description":"","frontmatter":{},"headers":[],"relativePath":"react/q12.md","filePath":"react/q12.md","lastUpdated":null}'),c={name:"react/q12.md"},n=a('<h1 id="q12-usecontext-与-context-api-如何跨组件传值" tabindex="-1">Q12：<code>useContext</code> 与 Context API 如何跨组件传值 <a class="header-anchor" href="#q12-usecontext-与-context-api-如何跨组件传值" aria-label="Permalink to &quot;Q12：`useContext` 与 Context API 如何跨组件传值&quot;">​</a></h1><p>Context 用于在组件树中共享全局数据，无需逐层 props 传递。</p><ol><li>创建：<code>const MyCtx = React.createContext(defaultValue)</code></li><li>提供：<code>&lt;MyCtx.Provider value={data}&gt;</code></li><li>消费： <ul><li>函数组件：<code>const data = useContext(MyCtx)</code></li><li>类组件：<code>static contextType = MyCtx</code> 或 <code>&lt;MyCtx.Consumer&gt;</code></li></ul></li></ol><p><strong>注意</strong>：Provider 的 value 变化时，所有使用该 Context 的组件都会重渲染。对于高频更新的数据，应拆分多个 Context，或用状态管理库进行细粒度订阅。</p>',4),s=[n];function l(r,d,i,_,x,p){return o(),e("div",null,s)}const h=t(c,[["render",l]]);export{C as __pageData,h as default};
